# W3: MLA-NoPE/DSA fixtures from the HF Glm5NextTextAttention + Glm5NextTextIndexer
# modules (tiny fp32, seed 7), plus the real-config indexer saturation check
# (S=2048 dense, S=2100 saturates at 2048).
#
# Run: /private/tmp/glm5-venv/bin/python crates/tang-llm/scripts/glm5_mla_fixture.py
# Writes tests/fixtures/glm5/mla/ (tiny fixtures, < 2 MB total) and prints the
# real-config saturation numbers recorded in meta.json["real_indexer"].
#
# hf_index_scores.bin (the module's per-pool scores, [130][32]) is regenerated by
# loading the fixture weights back into the module and recomputing index_scores
# verbatim from Glm5NextTextIndexer.forward — the Rust test uses it to detect
# relu-clamped exact ties, where torch.topk's ordering is an internal artifact.

import json, os, sys
import numpy as np
import torch
import torch.nn.functional as F
sys.path.insert(0, "/private/tmp/glm5-venv/lib/python3.12/site-packages")
from transformers.models.glm5_next.modeling_glm5_next import (
    Glm5NextTextConfig, Glm5NextTextAttention, Glm5NextTextIndexer, Glm5NextTextRMSNorm,
)

torch.manual_seed(7)

# tiny geometry: real-model ratios but small (MLA dims kept exact where they define layout)
cfg = Glm5NextTextConfig(
    hidden_size=64,
    num_attention_heads=4, num_key_value_heads=4,
    q_lora_rank=16, kv_lora_rank=8,
    qk_nope_head_dim=12, qk_rope_head_dim=0, v_head_dim=12,
    index_n_heads=3, index_head_dim=6, index_topk=16, index_kpool=4,
    index_kpool_always_select_tail=True,
    indexer_types=["full"],
    rms_norm_eps=1e-5,
    attention_bias=False,
    num_hidden_layers=1, layer_types=["deepseek_sparse_attention"],
)
cfg.indexer_types = ["full"]

OUT = "/private/tmp/glm5-w3-fix"
os.makedirs(OUT, exist_ok=True)

attn = Glm5NextTextAttention(cfg, 0).eval()   # layer_idx 0, indexer_types[0]="full" -> full indexer
torch.manual_seed(7); torch.nn.init.normal_(attn.indexer.index_kpool_compress_ape, std=0.5)
torch.manual_seed(11); torch.nn.init.normal_(attn.indexer.index_kpool_compress_gate, std=0.5)
for m in (attn, attn.indexer):
    for p in m.parameters():
        torch.nn.init.normal_(p, std=0.5) if False else None
# reseed all params deterministically
torch.manual_seed(7)
for m in (attn, attn.indexer):
    for name, p in m.named_parameters():
        torch.nn.init.normal_(p, std=0.5 / (p.shape[-1] ** 0.5))

B, S = 1, 130            # 130 = 32 pools * 4 + 2 tail -> exercises tail path
x = torch.randn(B, S, cfg.hidden_size)
mask = torch.ones(B, S, dtype=torch.bool)

sd = {k: v.detach().numpy() for k, v in attn.state_dict().items()}
meta = {
    "hidden": cfg.hidden_size, "n_head": cfg.num_attention_heads,
    "q_lora": cfg.q_lora_rank, "kv_lora": cfg.kv_lora_rank,
    "qk_nope": cfg.qk_nope_head_dim, "v_head": cfg.v_head_dim, "rope": 0,
    "idx_heads": cfg.index_n_heads, "idx_dim": cfg.index_head_dim,
    "topk": cfg.index_topk, "kpool": cfg.index_kpool, "tail": True,
    "eps": cfg.rms_norm_eps, "B": B, "S": S,
}

def save(name, t):
    a = t.detach().numpy()
    assert a.dtype == "float32"
    a.tofile(f"{OUT}/{name}.bin")
    meta.setdefault("shapes", {})[name] = list(a.shape)

for k, v in sd.items():
    save(k.replace(".", "_"), torch.tensor(v))
save("input_x", x)

with torch.no_grad():
    # reference intermediates, computed exactly as the module does
    q_resid = attn.q_a_layernorm(attn.q_a_proj(x))
    q = attn.q_b_proj(q_resid).view(B, S, -1, attn.qk_head_dim).transpose(1, 2)
    ckv = attn.kv_a_proj_with_mqa(x)
    kv_pass, k_rot = torch.split(ckv, [attn.kv_lora_rank, attn.qk_rope_head_dim], dim=-1)
    k_pass = attn.kv_a_layernorm(kv_pass)
    save("ref_q_resid", q_resid)
    save("ref_k_pass", k_pass.view(B, S, attn.kv_lora_rank))
    # indexer output
    topk_idx = attn.indexer(hidden_states=x, q_resid=q_resid, attention_mask=mask, past_key_values=None)
    assert topk_idx.dtype == torch.int32
    topk_idx.numpy().tofile(f"{OUT}/ref_topk_indices.bin")
    meta["shapes"]["ref_topk_indices"] = list(topk_idx.shape)
    # full attention forward
    out, aw, nxt = attn(x, attention_mask=mask, past_key_values=None)
    assert nxt is None
    save("ref_attn_out", out)

json.dump(meta, open(f"{OUT}/meta.json", "w"), indent=1)
print("OK", sorted(os.listdir(OUT)))
print("topk shape", topk_idx.shape, "topk sample row0[:8]:", topk_idx[0, 0, :8].tolist())


# ---- part 2 (from glm5_mla_fixture2.py): padded batch + real-config saturation ----
import json, os, sys, torch
sys.path.insert(0, "/private/tmp/glm5-venv/lib/python3.12/site-packages")
from transformers.models.glm5_next.modeling_glm5_next import (
    Glm5NextTextConfig, Glm5NextTextAttention,
)
torch.manual_seed(7)

def tiny_cfg():
    cfg = Glm5NextTextConfig(
        hidden_size=64, num_hidden_layers=1,
        num_attention_heads=4, num_key_value_heads=4,
        q_lora_rank=16, kv_lora_rank=8,
        qk_nope_head_dim=12, qk_rope_head_dim=0, v_head_dim=12,
        index_n_heads=3, index_head_dim=6, index_topk=16, index_kpool=4,
        index_kpool_always_select_tail=True,
        indexer_types=["full"], layer_types=["deepseek_sparse_attention"],
        rms_norm_eps=1e-5, attention_bias=False,
    )
    cfg.indexer_types = ["full"]
    return cfg

OUT = "/private/tmp/glm5-w3-fix"
torch.manual_seed(7)
attn = Glm5NextTextAttention(tiny_cfg(), 0).eval()
torch.manual_seed(7)
for m in (attn, attn.indexer):
    for name, p in m.named_parameters():
        torch.nn.init.normal_(p, std=0.5 / (p.shape[-1] ** 0.5))

# (a) padded batch: B=2, S=24, seq 0 has 5 pad tokens at the front
B, S = 2, 24
x = torch.randn(B, S, 64)
mask = torch.ones(B, S, dtype=torch.bool)
mask[0, :5] = False
with torch.no_grad():
    q_resid = attn.q_a_layernorm(attn.q_a_proj(x))
    topk = attn.indexer(hidden_states=x, q_resid=q_resid, attention_mask=mask, past_key_values=None)
    out, _, _ = attn(x, attention_mask=mask, past_key_values=None)
meta = json.load(open(f"{OUT}/meta.json"))
meta["padded"] = {"B": B, "S": S, "pad0": 5,
                  "shapes": {"p_topk_indices": [B, S, 19], "p_ref_attn_out": [B, S, 64],
                             "p_input_x": [B, S, 64], "p_mask": [B, S, 1]}}
topk.numpy().tofile(f"{OUT}/p_topk_indices.bin")
out.numpy().tofile(f"{OUT}/p_ref_attn_out.bin")
x.numpy().tofile(f"{OUT}/p_input_x.bin")
mask.numpy()[:, :, None].astype("float32").tofile(f"{OUT}/p_mask.bin")

# (b) real-config indexer behavior at S=2048 and S=2100 (indexer only, no attention)
cfg = Glm5NextTextConfig(
    hidden_size=4096, num_hidden_layers=1,
    num_attention_heads=64, num_key_value_heads=64,
    q_lora_rank=1536, kv_lora_rank=512,
    qk_nope_head_dim=256, qk_rope_head_dim=0, v_head_dim=256,
    index_n_heads=32, index_head_dim=128, index_topk=2048, index_kpool=4,
    index_kpool_always_select_tail=True,
    indexer_types=["full"], layer_types=["deepseek_sparse_attention"],
    rms_norm_eps=1e-5, attention_bias=False,
)
cfg.indexer_types = ["full"]
torch.manual_seed(7)
attn_r = Glm5NextTextAttention(cfg, 0).eval()
torch.manual_seed(7)
for m in (attn_r, attn_r.indexer):
    for name, p in m.named_parameters():
        torch.nn.init.normal_(p, std=0.5 / (p.shape[-1] ** 0.5))
res = {}
for S in (2048, 2100):
    torch.manual_seed(100 + S)
    x = torch.randn(1, S, 4096)
    mask = torch.ones(1, S, dtype=torch.bool)
    with torch.no_grad():
        q_resid = attn_r.q_a_layernorm(attn_r.q_a_proj(x))
        topk = attn_r.indexer(hidden_states=x, q_resid=q_resid, attention_mask=mask, past_key_values=None)
    t = topk[0]
    n_visible = (t >= 0).sum(-1)
    # causal check: every j <= i visible?
    allvis = True
    for i in range(S):
        v = set(t[i][t[i] >= 0].tolist())
        if len(v) != min(i + 1, 2048 + 3):  # 2048 + tail 3
            allvis = False; print(S, "row", i, "count", len(v), "want", min(i+1, 2048+3)); break
    res[S] = {"n_valid min/max": [int(n_visible.min()), int(n_visible.max())],
              "all_visible_up_to_2048+3": allvis}
    print(S, res[S])
meta["real_indexer"] = {str(k): v for k, v in res.items()}
json.dump(meta, open(f"{OUT}/meta.json", "w"), indent=1)
print("done")


# ---- part 3: hf_index_scores.bin — the module's per-pool scores, recomputed verbatim
# from Glm5NextTextIndexer.forward with the fixture weights, for tie detection in the
# Rust test. Run parts 1+2 first (they write the weight fixtures).
def _load(n, shape):
    return torch.from_numpy(np.fromfile(f"{OUT}/{n}.bin", dtype=np.float32).reshape(shape))

cfg2 = tiny_cfg()
attn2 = Glm5NextTextAttention(cfg2, 0).eval()
torch.manual_seed(7)
for m in (attn2, attn2.indexer):
    for name, p in m.named_parameters():
        torch.nn.init.normal_(p, std=0.5 / (p.shape[-1] ** 0.5))
idx = attn2.indexer
idx.wq_b.weight.data = _load("indexer_wq_b_weight", (18, 16))
idx.wk.weight.data = _load("indexer_wk_weight", (6, 64))
idx.k_norm.weight.data = _load("indexer_k_norm_weight", (6,))
idx.k_norm.bias.data = _load("indexer_k_norm_bias", (6,))
idx.weights_proj.weight.data = _load("indexer_weights_proj_weight", (3, 64))
idx.index_kpool_compress_gate.data = _load("indexer_index_kpool_compress_gate", (6, 64))
idx.index_kpool_compress_ape.data = _load("indexer_index_kpool_compress_ape", (4, 6))
x2 = _load("input_x", (1, 130, 64))
mask2 = torch.ones(1, 130, dtype=torch.bool)
with torch.no_grad():
    q2 = idx.wq_b(_load("ref_q_resid", (1, 130, 16))).view(1, 130, -1, idx.head_dim)
    k2 = idx.k_norm(idx.wk(x2)).view(1, 130, -1, idx.head_dim).squeeze(2)
    gate2 = F.linear(x2, idx.index_kpool_compress_gate)
    packed2 = torch.cat([k2, gate2, mask2.to(k2.dtype)[..., None]], dim=-1)
    pool_keys2, pool_indices2, _ = idx.get_pooled_states(packed2)
    scores2 = torch.matmul(q2.float(), pool_keys2.transpose(-1, -2).float().unsqueeze(1))
    scores2 = F.relu(scores2 * idx.softmax_scale)
    weights2 = F.linear(x2, idx.weights_proj.weight).float() * (idx.n_heads ** -0.5)
    index_scores2 = torch.matmul(weights2.unsqueeze(-2), scores2).squeeze(-2)
index_scores2[0].numpy().tofile(f"{OUT}/hf_index_scores.bin")
meta["shapes"]["hf_index_scores"] = [130, 32]
json.dump(meta, open(f"{OUT}/meta.json", "w"), indent=1)
print("hf_index_scores written", tuple(index_scores2.shape))
